// Bundled model photos (assets/models/<ICAO>.jpg, from Wikimedia Commons; credits in
// Settings and THIRD_PARTY_NOTICES.md): a typical aircraft of the type, shown when there is
// no Planespotters photo of the aircraft itself. Generated by scripts/models.mjs.
export const MODELS={};
export const modelPhoto=a=>{const t=String(a?.aircraft_type||'').toUpperCase(),m=MODELS[t];return m?{...m,src:`models/${t}.jpg`}:null;};
